INSERT INTO don_vi_tri_thuc (id, ma, tieu_de, loai, khai_niem_id, truong_phai_id, gia_tri_kich_hoat, dieu_kien_json, noi_dung, cau_hoi, nguon_id, chuong, trang_tu, trang_den, muc_tin_cay, nhan_su_dung, ly_do_nhan, phien_ban, trang_thai, nguoi_tao, nguoi_duyet, ghi_chu) VALUES
(209, 'PYT-DEC-NGUYEN-MAU-1', 'Nguyên mẫu số 1 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '1', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 1 mang phẩm chất cốt lõi: Theo Hans Decoz, Đường đời 1 đại diện cho tinh thần thủ lĩnh, ý chí tự lực và khát vọng khẳng định bản sắc cá nhân thông qua hành động quyết đoán.', 'NEN_TANG', 3, 'Ch.1', 6, 7, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(210, 'PYT-DEC-NGUYEN-MAU-2', 'Nguyên mẫu số 2 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '2', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 2 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 2 mang năng lượng hoà giải, tinh tế, thấu cảm và coi trọng sự hài hoà trong các mối quan hệ.', 'NEN_TANG', 3, 'Ch.1', 7, 8, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(211, 'PYT-DEC-NGUYEN-MAU-3', 'Nguyên mẫu số 3 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '3', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 3 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 3 tượng trưng cho sức sáng tạo nghệ thuật, khả năng diễn đạt ngôn từ xuất sắc và tinh thần lạc quan truyền cảm hứng.', 'NEN_TANG', 3, 'Ch.1', 8, 9, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(212, 'PYT-DEC-NGUYEN-MAU-4', 'Nguyên mẫu số 4 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '4', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 4 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 4 là người kiến tạo nền móng, làm việc có hệ thống, kiên trì và đề cao tính kỷ luật, an toàn.', 'NEN_TANG', 3, 'Ch.1', 9, 10, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(213, 'PYT-DEC-NGUYEN-MAU-5', 'Nguyên mẫu số 5 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '5', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 5 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 5 là biểu tượng của sự linh hoạt, đa tài, thích phiêu lưu khám phá và thích nghi nhanh với mọi biến động.', 'NEN_TANG', 3, 'Ch.1', 10, 11, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(214, 'PYT-DEC-NGUYEN-MAU-6', 'Nguyên mẫu số 6 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '6', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 6 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 6 là hình mẫu của sự nuôi dưỡng, tinh thần trách nhiệm, công bằng và khiếu thẩm mỹ hài hoà.', 'NEN_TANG', 3, 'Ch.1', 11, 12, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(215, 'PYT-DEC-NGUYEN-MAU-7', 'Nguyên mẫu số 7 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '7', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 7 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 7 sở hữu trí tuệ phân tích sắc sảo, trực giác chiều sâu và xu hướng tìm kiếm bản chất ẩn sau hiện tượng.', 'NEN_TANG', 3, 'Ch.1', 12, 13, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(216, 'PYT-DEC-NGUYEN-MAU-8', 'Nguyên mẫu số 8 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '8', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 8 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 8 mang năng lực điều hành vĩ mô, tầm nhìn chiến lược về tài chính và khát vọng tạo dựng thành tựu thực tế.', 'NEN_TANG', 3, 'Ch.1', 13, 14, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(217, 'PYT-DEC-NGUYEN-MAU-9', 'Nguyên mẫu số 9 theo Hans Decoz (Ch.1)', 'MO_TA', 14, 1, '9', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 9 mang phẩm chất cốt lõi: Theo Decoz, Đường đời 9 là người có tầm nhìn bao dung, giàu lòng vị tha, nhạy cảm nghệ thuật và hướng tới phụng sự xã hội.', 'NEN_TANG', 3, 'Ch.1', 14, 15, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(218, 'PYT-DEC-NGUYEN-MAU-11', 'Nguyên mẫu số 11 theo Hans Decoz (Ch.1)', 'MO_TA', 29, 1, '11', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 11 mang phẩm chất cốt lõi: Theo Decoz, Đường đời bậc thầy 11/2 mang khả năng khai sáng, trực giác nhạy bén và sức truyền cảm hứng tinh thần mạnh mẽ.', 'NEN_TANG', 3, 'Ch.1', 15, 16, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(219, 'PYT-DEC-NGUYEN-MAU-22', 'Nguyên mẫu số 22 theo Hans Decoz (Ch.1)', 'MO_TA', 29, 1, '22', NULL, 'Theo Hans Decoz (Ch.1), nguyên mẫu số 22 mang phẩm chất cốt lõi: Theo Decoz, Đường đời bậc thầy 22/4 (Master Builder) có năng lực biến những ý tưởng vĩ mô thành hệ thống và thiết chế thực tiễn lâu dài.', 'NEN_TANG', 3, 'Ch.1', 16, 17, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(220, 'PYT-DEC-NO-NGHIEP-13-AI', 'Cờ Nợ nghiệp 13/4 (Hans Decoz)', 'QUY_TAC', 15, 1, '13', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 13}', 'Theo Hans Decoz (Ch.1, tr.16), tổng trung gian 13/4 báo hiệu bài học về tính kỷ luật và sự tập trung bền bỉ: bạn có xu hướng gặp những công việc đòi hỏi nỗ lực lặp đi lặp lại và cần tránh tâm lý bỏ cuộc hay đi đường tắt.', 'AI', 3, 'Ch.1', 16, 16, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(221, 'PYT-DEC-NO-NGHIEP-13-DI', 'Hướng rèn luyện Cờ Nợ nghiệp 13/4 (Hans Decoz)', 'QUY_TAC', 15, 1, '13', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 13}', 'Để vượt qua thử thách Nợ nghiệp 13/4, Decoz khuyên bạn duy trì trật tự ngăn nắp, lập lịch trình rõ ràng và kiên trì hoàn tất từng mục tiêu một.', 'DI_THE_NAO', 3, 'Ch.1', 16, 16, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(222, 'PYT-DEC-NO-NGHIEP-14-AI', 'Cờ Nợ nghiệp 14/5 (Hans Decoz)', 'QUY_TAC', 15, 1, '14', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 14}', 'Theo Hans Decoz (Ch.1, tr.16–17), tổng trung gian 14/5 gắn với bài học sử dụng sự tự do một cách có chừng mực: cuộc sống của bạn thường có nhiều biến động bất ngờ đòi hỏi khả năng thích nghi và tự kiểm soát.', 'AI', 3, 'Ch.1', 16, 17, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(223, 'PYT-DEC-NO-NGHIEP-14-DI', 'Hướng rèn luyện Cờ Nợ nghiệp 14/5 (Hans Decoz)', 'QUY_TAC', 15, 1, '14', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 14}', 'Để chuyển hoá Nợ nghiệp 14/5, Decoz khuyên bạn giữ sự điều độ trong lối sống, cam kết với mục tiêu dài hạn và giữ vững trọng tâm cảm xúc.', 'DI_THE_NAO', 3, 'Ch.1', 16, 17, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(224, 'PYT-DEC-NO-NGHIEP-16-AI', 'Cờ Nợ nghiệp 16/7 (Hans Decoz)', 'QUY_TAC', 15, 1, '16', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 16}', 'Theo Hans Decoz (Ch.1, tr.17–18), tổng trung gian 16/7 phản ánh quá trình tái thiết cái tôi (ego) để đạt tới trí tuệ tinh thần sâu sắc hơn: những khuôn mẫu cũ thường được thay thế để bạn trưởng thành về nhận thức.', 'AI', 3, 'Ch.1', 17, 18, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(225, 'PYT-DEC-NO-NGHIEP-16-DI', 'Hướng rèn luyện Cờ Nợ nghiệp 16/7 (Hans Decoz)', 'QUY_TAC', 15, 1, '16', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 16}', 'Để chuyển hoá Nợ nghiệp 16/7, Decoz khuyên bạn nuôi dưỡng sự khiêm tốn, lắng nghe trực giác nội tâm và đặt chất lượng các mối quan hệ lên trên hình thức bề ngoài.', 'DI_THE_NAO', 3, 'Ch.1', 17, 18, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(226, 'PYT-DEC-NO-NGHIEP-19-AI', 'Cờ Nợ nghiệp 19/1 (Hans Decoz)', 'QUY_TAC', 15, 1, '19', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 19}', 'Theo Hans Decoz (Ch.1, tr.18), tổng trung gian 19/1 là bài học về sự tự lực song hành cùng tinh thần kết nối: bạn có năng lực tự đứng vững mạnh mẽ nhưng dễ khép mình khi cần sự hỗ trợ từ người khác.', 'AI', 3, 'Ch.1', 18, 18, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(227, 'PYT-DEC-NO-NGHIEP-19-DI', 'Hướng rèn luyện Cờ Nợ nghiệp 19/1 (Hans Decoz)', 'QUY_TAC', 15, 1, '19', '{"chi_so": "DECOZ_NO_NGHIEP", "chua": 19}', 'Để chuyển hoá Nợ nghiệp 19/1, Decoz khuyên bạn vừa phát huy bản lĩnh độc lập vừa mở lòng hợp tác, biết lắng nghe lời khuyên và chia sẻ thành quả với cộng đồng.', 'DI_THE_NAO', 3, 'Ch.1', 18, 18, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(228, 'PYT-DEC-LP-1-AI', 'Số Đường đời 1 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '1', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "1"}', 'Theo Hans Decoz, Đường đời 1 đại diện cho tinh thần thủ lĩnh, ý chí tự lực và khát vọng khẳng định bản sắc cá nhân thông qua hành động quyết đoán.', 'AI', 3, 'Ch.2', 21, 22, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(229, 'PYT-DEC-LP-1-NGHE', 'Số Đường đời 1 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '1', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "1"}', 'Decoz khuyến nghị bạn tránh sự cứng nhắc, độc đoán và học cách tin tưởng cộng sự; bạn có xu hướng hợp với vai trò doanh nhân, quản trị viên, kỹ sư trưởng hoặc nhà cải cách.', 'DI_THE_NAO', 3, 'Ch.2', 21, 22, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(230, 'PYT-DEC-LP-2-AI', 'Số Đường đời 2 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '2', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "2"}', 'Theo Decoz, Đường đời 2 mang năng lượng hoà giải, tinh tế, thấu cảm và coi trọng sự hài hoà trong các mối quan hệ.', 'AI', 3, 'Ch.2', 22, 23, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(231, 'PYT-DEC-LP-2-NGHE', 'Số Đường đời 2 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '2', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "2"}', 'Decoz cho rằng bạn cần tránh nhạy cảm quá mức trước lời phê bình và dám nói lên chính kiến; phù hợp với công tác ngoại giao, tâm lý, chăm sóc y tế, âm nhạc và hoà giải.', 'DI_THE_NAO', 3, 'Ch.2', 22, 23, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(232, 'PYT-DEC-LP-3-AI', 'Số Đường đời 3 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '3', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "3"}', 'Theo Decoz, Đường đời 3 tượng trưng cho sức sáng tạo nghệ thuật, khả năng diễn đạt ngôn từ xuất sắc và tinh thần lạc quan truyền cảm hứng.', 'AI', 3, 'Ch.2', 23, 24, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(233, 'PYT-DEC-LP-3-NGHE', 'Số Đường đời 3 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '3', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "3"}', 'Decoz lưu ý bạn cần rèn tính kỷ luật tài chính và tập trung hoàn tất mục tiêu thay vì bỏ dở giữa chừng; phù hợp với truyền thông, văn chương, diễn thuyết, thiết kế và nghệ thuật.', 'DI_THE_NAO', 3, 'Ch.2', 23, 24, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(234, 'PYT-DEC-LP-4-AI', 'Số Đường đời 4 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '4', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "4"}', 'Theo Decoz, Đường đời 4 là người kiến tạo nền móng, làm việc có hệ thống, kiên trì và đề cao tính kỷ luật, an toàn.', 'AI', 3, 'Ch.2', 25, 26, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(235, 'PYT-DEC-LP-4-NGHE', 'Số Đường đời 4 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '4', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "4"}', 'Decoz khuyên bạn học cách linh hoạt trước thay đổi và tránh ôm đồm quá nhiều việc; nghề nghiệp phù hợp gồm kỹ sư, kiến trúc, kế toán - kiểm toán, quản lý dự án và lập trình.', 'DI_THE_NAO', 3, 'Ch.2', 25, 26, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(236, 'PYT-DEC-LP-5-AI', 'Số Đường đời 5 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '5', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "5"}', 'Theo Decoz, Đường đời 5 là biểu tượng của sự linh hoạt, đa tài, thích phiêu lưu khám phá và thích nghi nhanh với mọi biến động.', 'AI', 3, 'Ch.2', 26, 27, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(237, 'PYT-DEC-LP-5-NGHE', 'Số Đường đời 5 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '5', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "5"}', 'Decoz lưu ý bạn cần xác định định hướng dài hạn để không bị phân tán năng lượng; phù hợp với kinh doanh thương mại, báo chí, du lịch, tổ chức sự kiện và tư vấn.', 'DI_THE_NAO', 3, 'Ch.2', 26, 27, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(238, 'PYT-DEC-LP-6-AI', 'Số Đường đời 6 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '6', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "6"}', 'Theo Decoz, Đường đời 6 là hình mẫu của sự nuôi dưỡng, tinh thần trách nhiệm, công bằng và khiếu thẩm mỹ hài hoà.', 'AI', 3, 'Ch.2', 27, 29, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(239, 'PYT-DEC-LP-6-NGHE', 'Số Đường đời 6 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '6', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "6"}', 'Decoz khuyên bạn đặt ranh giới hợp lý để không hy sinh bản thân quá mức hoặc can thiệp sâu vào việc của người khác; phù hợp với trị liệu, giáo dục, thiết kế, ẩm thực và quản lý nhân sự.', 'DI_THE_NAO', 3, 'Ch.2', 27, 29, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(240, 'PYT-DEC-LP-7-AI', 'Số Đường đời 7 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '7', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "7"}', 'Theo Decoz, Đường đời 7 sở hữu trí tuệ phân tích sắc sảo, trực giác chiều sâu và xu hướng tìm kiếm bản chất ẩn sau hiện tượng.', 'AI', 3, 'Ch.2', 29, 30, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(241, 'PYT-DEC-LP-7-NGHE', 'Số Đường đời 7 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '7', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "7"}', 'Decoz khuyên bạn tránh cô lập bản thân hoặc hoài nghi quá mức, nên kết nối cảm xúc với mọi người; phù hợp với nghiên cứu, khoa học dữ liệu, học thuật, luật học và triết học.', 'DI_THE_NAO', 3, 'Ch.2', 29, 30, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(242, 'PYT-DEC-LP-8-AI', 'Số Đường đời 8 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '8', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "8"}', 'Theo Decoz, Đường đời 8 mang năng lực điều hành vĩ mô, tầm nhìn chiến lược về tài chính và khát vọng tạo dựng thành tựu thực tế.', 'AI', 3, 'Ch.2', 30, 31, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(243, 'PYT-DEC-LP-8-NGHE', 'Số Đường đời 8 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '8', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "8"}', 'Decoz lưu ý bạn cần cân bằng giữa mục tiêu vật chất và đời sống tinh thần; phù hợp với quản lý cấp cao, đầu tư tài chính, bất động sản và hành chính công.', 'DI_THE_NAO', 3, 'Ch.2', 30, 31, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(244, 'PYT-DEC-LP-9-AI', 'Số Đường đời 9 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '9', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "9"}', 'Theo Decoz, Đường đời 9 là người có tầm nhìn bao dung, giàu lòng vị tha, nhạy cảm nghệ thuật và hướng tới phụng sự xã hội.', 'AI', 3, 'Ch.2', 31, 32, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(245, 'PYT-DEC-LP-9-NGHE', 'Số Đường đời 9 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '9', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "9"}', 'Decoz khuyên bạn học cách buông bỏ quá khứ và cân bằng giữa cho đi với chăm sóc bản thân; phù hợp với giáo dục, từ thiện, nghệ thuật, ngoại giao và y tế.', 'DI_THE_NAO', 3, 'Ch.2', 31, 32, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(246, 'PYT-DEC-LP-11-AI', 'Số Đường đời 11 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '11', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "11"}', 'Theo Decoz, Đường đời bậc thầy 11/2 mang khả năng khai sáng, trực giác nhạy bén và sức truyền cảm hứng tinh thần mạnh mẽ.', 'AI', 3, 'Ch.2', 32, 33, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(247, 'PYT-DEC-LP-11-NGHE', 'Số Đường đời 11 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '11', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "11"}', 'Decoz lưu ý bạn cần giữ đôi chân thực tế trên mặt đất để giảm căng thẳng thần kinh; phù hợp với diễn giả, nhà giáo, nghệ sĩ, nhà tư vấn và nghiên cứu nhân văn.', 'DI_THE_NAO', 3, 'Ch.2', 32, 33, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(248, 'PYT-DEC-LP-22-AI', 'Số Đường đời 22 — Tính cách cốt lõi (Decoz)', 'QUY_TAC', 14, 1, '22', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "22"}', 'Theo Decoz, Đường đời bậc thầy 22/4 (Master Builder) có năng lực biến những ý tưởng vĩ mô thành hệ thống và thiết chế thực tiễn lâu dài.', 'AI', 3, 'Ch.2', 33, 34, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(249, 'PYT-DEC-LP-22-NGHE', 'Số Đường đời 22 — Lưu ý & Nghề nghiệp (Decoz)', 'QUY_TAC', 14, 1, '22', '{"chi_so": "DECOZ_DUONG_DOI", "bang": "22"}', 'Decoz khuyến nghị bạn vượt qua nỗi sợ thất bại và chia nhỏ mục tiêu lớn thành từng bước khả thi; phù hợp với quản lý vĩ mô, kiến trúc hệ thống, chính sách công và lãnh đạo doanh nghiệp.', 'DI_THE_NAO', 3, 'Ch.2', 33, 34, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(250, 'PYT-DEC-EXP-1', 'Số Biểu đạt (Expression) 1 — Toàn bộ chữ cái tên (Decoz Ch.3)', 'QUY_TAC', 16, 1, '1', '{"chi_so": "DECOZ_BIEU_DAT", "bang": "1"}', 'Theo Hans Decoz (Ch.3, tr.69), Số Biểu đạt (Expression) 1 tính từ toàn bộ chữ cái họ tên cho thấy năng lực tự nhiên và mục tiêu thể hiện bản thân của bạn mang phẩm chất số 1.', 'AI', 3, 'Ch.3', 69, 69, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
