(314, 'PYT-DEC-DOI-TEN-THAN-TRONG', 'Lời khuyên về việc thay đổi tên gọi (Decoz Ch.3, tr.104)', 'MO_TA', 18, 1, NULL, NULL, 'Trong Chương 3 (tr.104), Hans Decoz bàn về tác động của việc đổi tên hoặc ghép họ sau kết hôn lên Minor Personality Number và khuyên cần thận trọng khi đổi tên.', 'DI_THE_NAO', 3, 'Ch.3', 104, 104, 'THAP', 'THAN_TRONG', 'Theo Mục 9.1: Lời khuyên đổi tên thuộc nhãn THAN_TRONG, chỉ lưu trong Kho và không hiển thị ở Khám phá.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(315, 'PYT-DEC-DO-THAT-LAC-KHONG-DUNG', 'Tìm đồ thất lạc bằng con số (Finding Lost Objects - Decoz Ch.7)', 'LICH_SU', 14, 1, NULL, NULL, 'Phương pháp dùng số ngẫu nhiên để đoán vị trí đồ vật bị thất lạc trong Chương 7 (tr.236–242) của Hans Decoz.', 'NEN_TANG', 3, 'Ch.7', 236, 242, 'THAP', 'KHONG_DUNG', 'Theo Mục 9.1: Phương pháp tìm đồ thất lạc mang tính bói toán, gắn nhãn KHONG_DUNG.', 1, 'DA_DUYET', 'system', 'admin', NULL);
